using System.Globalization;
using System.Runtime.CompilerServices;
using MarqSpec.FuturesLiquidityDashboard.Core.Instruments;
using MarqSpec.FuturesLiquidityDashboard.Core.Market;
using MarqSpec.FuturesLiquidityDashboard.Core.Sessions;
using MarqSpec.FuturesLiquidityDashboard.Ingestion.Feeds;

namespace MarqSpec.FuturesLiquidityDashboard.Ingestion.Synthetic;

/// <summary>
/// The no-credentials feed (ARCHITECTURE.md D-12): one <see cref="SyntheticInstrumentSimulator"/> per instrument,
/// stepped on a timer. History is generated by stepping the same simulator from the history start to now, so the
/// live market continues exactly where the warmup ended. Every event is labelled SIMULATED (D-14). Like the live
/// feed, it streams depth only for the products <see cref="DepthDemand"/> wants and top-of-book quotes for the rest
/// (REQUIREMENTS.md FR-54).
/// </summary>
public sealed class SyntheticMarketFeed : IMarketDataFeed, IHistoricalTradeSource
{
    private const int HistoryStepMs = 250;
    private readonly SyntheticFeedOptions _options;
    private readonly ExchangeCalendar _calendar;
    private readonly TimeProvider _time;
    private readonly DepthDemand _depth;
    private readonly Dictionary<InstrumentRoot, SyntheticInstrumentSimulator> _simulators = [];
    private readonly Lock _gate = new();

    /// <param name="depth">Which products get depth (REQUIREMENTS.md FR-54); every product when null.</param>
    public SyntheticMarketFeed(SyntheticFeedOptions options, ExchangeCalendar calendar, TimeProvider time, DepthDemand? depth = null)
    {
        _options = options ?? throw new ArgumentNullException(nameof(options));
        _calendar = calendar ?? throw new ArgumentNullException(nameof(calendar));
        _time = time ?? throw new ArgumentNullException(nameof(time));
        _depth = depth ?? DepthDemand.Everything(time);
    }

    public string Name => "synthetic";

    public FeedProvenance Provenance => FeedProvenance.Simulated;

    /// <summary>
    /// The activity multiplier by time of day in Chicago: busiest in the first and last half hour of regular
    /// trading hours (08:30–15:00 CT), quieter overnight. The synthetic market never closes, so a demo works at
    /// weekends; the status still reports whether the real exchange is open.
    /// </summary>
    public double TimeOfDay(long timeMs)
    {
        var local = _calendar.ToCentral(DateTimeOffset.FromUnixTimeMilliseconds(timeMs)).TimeOfDay;
        var open = new TimeSpan(8, 30, 0);
        var close = new TimeSpan(15, 0, 0);
        if (local < open || local >= close)
        {
            return 0.45;
        }

        return local < open.Add(TimeSpan.FromMinutes(30)) || local >= close.Subtract(TimeSpan.FromMinutes(30)) ? 1.4 : 1.0;
    }

    public Task<IReadOnlyList<TradeEvent>> GetTradesAsync(InstrumentSpec instrument, long fromMs, long toMs, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(instrument);
        return Task.Run(() => GenerateHistory(instrument, fromMs, toMs, cancellationToken), cancellationToken);
    }

    public async IAsyncEnumerable<MarketEvent> StreamAsync(
        IReadOnlyList<InstrumentSpec> instruments,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(instruments);
        var cursor = OpenCursor(instruments);
        foreach (var e in cursor.Prime(_time.GetUtcNow().ToUnixTimeMilliseconds()))
        {
            yield return e;
        }

        using var timer = new PeriodicTimer(TimeSpan.FromMilliseconds(_options.StepMs), _time);
        while (await timer.WaitForNextTickAsync(cancellationToken).ConfigureAwait(false))
        {
            foreach (var e in cursor.Step(_time.GetUtcNow().ToUnixTimeMilliseconds()))
            {
                yield return e;
            }
        }
    }

    /// <summary>
    /// The live loop <see cref="StreamAsync"/> runs on its timer. A test steps it directly, so a slow runner
    /// cannot trip a wall-clock timeout.
    /// </summary>
    internal SyntheticLiveCursor OpenCursor(IReadOnlyList<InstrumentSpec> instruments)
    {
        ArgumentNullException.ThrowIfNull(instruments);
        return new SyntheticLiveCursor(this, instruments);
    }

    /// <summary>One synthetic stream: the opening events, then one <see cref="Step"/> per timer tick.</summary>
    internal sealed class SyntheticLiveCursor
    {
        private readonly SyntheticMarketFeed _feed;
        private readonly IReadOnlyList<InstrumentSpec> _instruments;
        private readonly HashSet<InstrumentRoot> _available;
        private readonly Dictionary<InstrumentRoot, bool> _depthOn = [];
        private readonly Dictionary<InstrumentRoot, (long? Bid, long? Ask)> _tops = [];

        internal SyntheticLiveCursor(SyntheticMarketFeed feed, IReadOnlyList<InstrumentSpec> instruments)
        {
            _feed = feed;
            _instruments = instruments;
            _available = instruments.Select(s => s.Root).ToHashSet();
        }

        internal List<MarketEvent> Prime(long nowMs)
        {
            var wanted = _feed._depth.Wanted(_available, out _);
            var start = new List<MarketEvent>();
            lock (_feed._gate)
            {
                foreach (var spec in _instruments)
                {
                    if (!_feed._simulators.TryGetValue(spec.Root, out var simulator))
                    {
                        simulator = _feed.Create(spec);
                        _feed._simulators[spec.Root] = simulator;
                        Route(simulator.Start(nowMs), simulator, wanted.Contains(spec.Root), nowMs, _tops, start);
                    }
                    else
                    {
                        Route(simulator.Resync(nowMs), simulator, wanted.Contains(spec.Root), nowMs, _tops, start);
                    }

                    _depthOn[spec.Root] = wanted.Contains(spec.Root);
                }
            }

            return start;
        }

        internal List<MarketEvent> Step(long nowMs)
        {
            var wanted = _feed._depth.Wanted(_available, out _);
            var batch = new List<MarketEvent>();
            lock (_feed._gate)
            {
                foreach (var spec in _instruments)
                {
                    var simulator = _feed._simulators[spec.Root];
                    var on = wanted.Contains(spec.Root);
                    var was = _depthOn[spec.Root];
                    var events = simulator.Step(nowMs);
                    if (on && !was && simulator.Connected)
                    {
                        // Depth switched on: this step's depth changes are dropped and a fresh baseline follows, as
                        // after a new order-book subscription upstream.
                        Route(events, simulator, depth: false, nowMs, _tops, batch, quotes: false);
                        batch.AddRange(simulator.Resync(nowMs));
                        _depthOn[spec.Root] = true;
                    }
                    else if (!on && was)
                    {
                        Route(events, simulator, depth: false, nowMs, _tops, batch);
                        if (simulator.Connected)
                        {
                            batch.Add(simulator.CurrentStatus(nowMs, depthSubscribed: false));
                        }

                        _depthOn[spec.Root] = false;
                    }
                    else
                    {
                        Route(events, simulator, was, nowMs, _tops, batch);
                    }
                }
            }

            return batch;
        }
    }

    /// <summary>
    /// Passes a simulator's events on. Without depth, the book events are dropped, a status says depth is off, and
    /// a quote follows whenever the top of book moved, as the quote stream would send it.
    /// </summary>
    private static void Route(
        IReadOnlyList<MarketEvent> events,
        SyntheticInstrumentSimulator simulator,
        bool depth,
        long nowMs,
        Dictionary<InstrumentRoot, (long? Bid, long? Ask)> tops,
        List<MarketEvent> output,
        bool quotes = true)
    {
        if (depth)
        {
            output.AddRange(events);
            return;
        }

        foreach (var e in events)
        {
            switch (e)
            {
                case DepthSnapshotEvent or DepthUpdateEvent or BookResetEvent:
                    break;
                case FeedStatusEvent status:
                    tops.Remove(status.Root);
                    output.Add(status with { DepthSubscribed = false });
                    break;
                default:
                    output.Add(e);
                    break;
            }
        }

        if (quotes && simulator.Connected && events.Count > 0)
        {
            var quote = simulator.Quote(nowMs);
            var top = (quote.BidTicks, quote.AskTicks);
            if (!tops.TryGetValue(quote.Root, out var last) || last != top)
            {
                tops[quote.Root] = top;
                output.Add(quote);
            }
        }
    }

    /// <summary>
    /// Steps a fresh simulator from <paramref name="fromMs"/> to <paramref name="toMs"/> and keeps it for live
    /// streaming. Prints are combined per second, price and aggressor so a day of history stays small.
    /// </summary>
    internal IReadOnlyList<TradeEvent> GenerateHistory(InstrumentSpec spec, long fromMs, long toMs, CancellationToken cancellationToken)
    {
        var simulator = Create(spec);
        simulator.Start(fromMs);
        var buckets = new SortedDictionary<(long Second, long Price, BookSide Aggressor), long>();
        for (var t = fromMs + HistoryStepMs; t <= toMs; t += HistoryStepMs)
        {
            if ((t - fromMs) % 600_000 == 0)
            {
                cancellationToken.ThrowIfCancellationRequested();
            }

            foreach (var e in simulator.Step(t))
            {
                if (e is TradeEvent trade)
                {
                    var key = (trade.SourceTimeMs / 1000, trade.PriceTicks, trade.Aggressor);
                    buckets[key] = buckets.GetValueOrDefault(key) + trade.Quantity;
                }
            }
        }

        lock (_gate)
        {
            _simulators[spec.Root] = simulator;
        }

        var n = 0;
        return buckets.Select(b => new TradeEvent
        {
            Root = spec.Root,
            ContractId = spec.ContractId,
            // Mid-second, but never after the end of the requested window (the last second can be partial).
            SourceTimeMs = Math.Min((b.Key.Second * 1000) + 500, toMs),
            ReceivedTimeMs = Math.Min((b.Key.Second * 1000) + 500, toMs),
            Epoch = 0,
            Sequence = ++n,
            PriceTicks = b.Key.Price,
            Quantity = b.Value,
            Aggressor = b.Key.Aggressor,
            TradeId = string.Create(CultureInfo.InvariantCulture, $"{spec.Root}-H-{n}"),
        }).ToList();
    }

    /// <summary>
    /// Steps the same simulators the live stream uses, without the timer, so a test can push a burst through the
    /// ingest buffer (REQUIREMENTS.md NFR-4). Outages follow <see cref="SyntheticFeedOptions.OutageIntervalSeconds"/>.
    /// </summary>
    internal List<MarketEvent> Burst(IReadOnlyList<InstrumentSpec> instruments, long startMs, int steps, int stepMs)
    {
        ArgumentNullException.ThrowIfNull(instruments);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(steps);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(stepMs);
        var events = new List<MarketEvent>();
        var available = instruments.Select(s => s.Root).ToHashSet();
        var wanted = _depth.Wanted(available, out _);
        var tops = new Dictionary<InstrumentRoot, (long? Bid, long? Ask)>();
        lock (_gate)
        {
            foreach (var spec in instruments)
            {
                if (!_simulators.TryGetValue(spec.Root, out var simulator))
                {
                    simulator = Create(spec);
                    _simulators[spec.Root] = simulator;
                    Route(simulator.Start(startMs), simulator, wanted.Contains(spec.Root), startMs, tops, events);
                }
            }

            for (var i = 1; i <= steps; i++)
            {
                var now = startMs + ((long)i * stepMs);
                foreach (var spec in instruments)
                {
                    Route(_simulators[spec.Root].Step(now), _simulators[spec.Root], wanted.Contains(spec.Root), now, tops, events);
                }
            }
        }

        return events;
    }

    private SyntheticInstrumentSimulator Create(InstrumentSpec spec)
    {
        var profile = SyntheticProfile.For(spec);
        return new SyntheticInstrumentSimulator(
            spec,
            profile,
            unchecked(_options.Seed + (SeedOffset(spec.Root) * 7919)),
            _options.LevelsPerSide,
            (double)spec.ToTicks(profile.StartPrice),
            TimeOfDay,
            _options.OutageIntervalSeconds * 1000,
            _options.OutageDurationMs);
    }

    /// <summary>ES, GC and CL keep the MVP's seeds (0, 1, 2); any other root gets a stable hash, so each market differs.</summary>
    internal static int SeedOffset(InstrumentRoot root)
    {
        for (var i = 0; i < InstrumentCatalog.Core.Count; i++)
        {
            if (InstrumentCatalog.Core[i].Root == root)
            {
                return i;
            }
        }

        return 3 + (root.StableHash() % 100_000);
    }
}
